// Format rekap sisa slot dan daftar mahasiswa per dosen
const raw = $input.first().json;
const data = raw.body || raw.data || raw;

const totalLecturers = data.totalLecturers || 0;
const totalQuotaUsed = data.totalQuotaUsed || data.selectedStudents || 0;
const totalQuotaMax = data.totalQuotaMax || 0;
const selectionPercentage = data.selectionPercentage || 0;
const listDosen = data.lecturerDetails || [];

let reportText = `📊 *REKAP SLOT DOSEN & DAFTAR MAHASISWA*\n\n`;
reportText += `Total Dosen: ${totalLecturers}\n`;
reportText += `Kuota Digunakan: ${totalQuotaUsed} / ${totalQuotaMax} (${selectionPercentage}%)\n\n`;
reportText += `--- *DAFTAR DOSEN & SISA SLOT* ---\n\n`;

if (listDosen.length > 0) {
  listDosen.forEach((dosen, i) => {
    const statusSlot = dosen.isFull ? "🔴 FULL" : `🟢 Sisa ${dosen.sisaSlot} Slot`;
    reportText += `${i + 1}. *${dosen.nama}*\n`;
    reportText += `   Status: ${statusSlot} (${dosen.terisi}/${dosen.kuotaMax})\n`;
    if (dosen.daftarMahasiswa && dosen.daftarMahasiswa.length > 0) {
      reportText += `   Mahasiswa:\n`;
      dosen.daftarMahasiswa.forEach((mhs) => {
        reportText += `   • ${mhs.nama} (${mhs.nim}) - ${mhs.statusBimbingan}\n`;
      });
    } else {
      reportText += `   Mahasiswa: (Belum ada)\n`;
    }
    reportText += `\n`;
  });
} else {
  reportText += `(Belum ada data dosen terdeteksi)\n`;
}

return [{ json: { reportText } }];
